/**
 * @summary Get bid stats for a requirement
 */
export const getGetRequirementStatsUrl = (id: string) => {
  return `/api/requirements/stats/${id}`;
};

export const getRequirementStats = async (
  id: string,
  options?: RequestInit,
): Promise<RequirementStats> => {
  return customFetch<RequirementStats>(getGetRequirementStatsUrl(id), {
    ...options,
    method: "GET",
  });
};

export const getGetRequirementStatsQueryKey = (id: string) => {
  return [`/api/requirements/stats/${id}`] as const;
};

export const getGetRequirementStatsQueryOptions = <
  TData = Awaited<ReturnType<typeof getRequirementStats>>,
  TError = ErrorType<unknown>,
>(
  id: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getRequirementStats>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetRequirementStatsQueryKey(id);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getRequirementStats>>
  > = ({ signal }) => getRequirementStats(id, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!id,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getRequirementStats>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetRequirementStatsQueryResult = NonNullable<
  Awaited<ReturnType<typeof getRequirementStats>>
>;
export type GetRequirementStatsQueryError = ErrorType<unknown>;

/**
 * @summary Get bid stats for a requirement
 */

export function useGetRequirementStats<
  TData = Awaited<ReturnType<typeof getRequirementStats>>,
  TError = ErrorType<unknown>,
>(
  id: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getRequirementStats>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetRequirementStatsQueryOptions(id, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
